type Finding = {
  route: string; viewport: string; theme: string;
  pageOverflowPx: number; wide: string[]; smallTaps: number; errors: string[]; status: number | null; shot?: string;
};

async function inspect(page: import("playwright").Page, vw: number) {
  return page.evaluate((vw) => {
    const doc = document.documentElement;
    const pageOverflowPx = Math.max(0, Math.max(doc.scrollWidth, document.body.scrollWidth) - doc.clientWidth);
    const desc = (el: Element) => {
      const e = el as HTMLElement;
      const cls = typeof e.className === "string" ? e.className.trim().split(/\s+/).slice(0, 3).join(".") : "";
      return `${el.tagName.toLowerCase()}${e.id ? "#" + e.id : ""}${cls ? "." + cls : ""}`;
    };
    const scrollsX = (el: Element | null): boolean => {
      for (let p = el; p && p !== document.body; p = p.parentElement) {
        const cs = getComputedStyle(p);
        if (/(auto|scroll|hidden|clip)/.test(cs.overflowX) && (p as HTMLElement).clientWidth <= vw + 1) return true;
      }
      return false;
    };
    const ignorable = (el: Element): boolean => {
      for (let p: Element | null = el; p; p = p.parentElement) {
        const cs = getComputedStyle(p);
        if (p.getAttribute("aria-hidden") === "true" || cs.pointerEvents === "none" || cs.visibility === "hidden" || cs.display === "none") return true;
      }
      return false;
    };
    const wide: string[] = [];
    const seen = new Set<string>();
    for (const el of Array.from(document.body.querySelectorAll("*"))) {
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) continue;
      if (r.right <= vw + 1 && r.left >= -1) continue;
      const cs = getComputedStyle(el);
      if (cs.position === "fixed" && (r.left >= vw || r.right <= 0)) continue; // off-canvas drawer
      if (["svg", "path", "circle", "rect", "g", "line", "polyline", "polygon", "defs", "use", "stop"].includes(el.tagName.toLowerCase())) continue;
      if (scrollsX(el.parentElement) || ignorable(el)) continue;
      // an element is "wide" if its OWN box crosses the edge; skip children of an already-reported ancestor
      let p = el.parentElement, dup = false;
      while (p) { if (seen.has(desc(p) + Math.round(p.getBoundingClientRect().right))) { dup = true; break; } p = p.parentElement; }
      if (dup) continue;
      const key = desc(el) + Math.round(r.right);
      seen.add(key);
      wide.push(`${desc(el)} [${Math.round(r.left)}..${Math.round(r.right)}] "${(el.textContent || "").trim().slice(0, 30)}"`);
      if (wide.length >= 12) break;
    }
    let smallTaps = 0;
    if (vw <= 820) {
      for (const el of Array.from(document.querySelectorAll("button, a[href], input:not([type=hidden]), select, textarea, [role=button]"))) {
        const r = el.getBoundingClientRect();
        if (r.width === 0 || r.height === 0 || ignorable(el)) continue;
        if (r.height < 40 && !(el as HTMLElement).closest("[data-allow-small]")) smallTaps++;
      }
    }
    const hasViewportMeta = !!document.querySelector('meta[name="viewport"]');
    return { pageOverflowPx, wide, smallTaps, hasViewportMeta };
  }, vw);
}

async function main() {
  const base = (arg("base", "http://localhost:3000") as string).replace(/\/$/, "");
  const cookie = arg("cookie") ?? process.env.RESP_COOKIE;
  const cookieName = arg("cookie-name") ?? process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
  const vps = (arg("viewports", "360x740,390x844,414x896,768x1024,1024x768,1440x900") as string).split(",").map((s) => s.split("x").map(Number) as [number, number]);
  const themes = (arg("themes", "dark,light") as string).split(",");
  const out = arg("out");
  const shots = flag("shots") && !!out;
  const settle = Number(arg("settle", "1200"));
  let routes = arg("routes") ? (arg("routes") as string).split(",") : [...DEFAULT_ROUTES];
  if (out) mkdirSync(out, { recursive: true });

  const browser: Browser = await chromium.launch();
  const mkCtx = async (w: number, h: number, theme: string) => {
    const ctx = await browser.newContext({
      viewport: { width: w, height: h }, isMobile: w <= 820, hasTouch: w <= 820, deviceScaleFactor: 1,
      colorScheme: theme === "light" ? "light" : "dark",
