  };

  if (flag("discover") || flag("tabs")) {
    const ctx = await mkCtx(1440, 900, "dark");
    const pg = await ctx.newPage();
    for (const d of DISCOVER) {
      try {
        await pg.goto(base + d.list, { waitUntil: "domcontentloaded", timeout: 60000 });
        await pg.waitForTimeout(800);
        const hrefs: string[] = await pg.$$eval("a[href]", (as) => as.map((a) => (a as HTMLAnchorElement).getAttribute("href") || ""));
        const uniq = [...new Set(hrefs.filter((h) => d.re.test(h)))].slice(0, d.max);
        routes.push(...uniq);
        if (flag("tabs") && d.list === "/dashboard/servers") {
          for (const u of uniq) for (const t of new Set([...VPS_TABS, ...GAME_TABS])) routes.push(`${u}?tab=${t}`);
        }
      } catch (e) { console.error("discover failed for", d.list, (e as Error).message); }
    }
    await ctx.close();
    routes = [...new Set(routes)];
  }

  const results: Finding[] = [];
  for (const theme of themes) {
    for (const [w, h] of vps) {
      const ctx = await mkCtx(w, h, theme);
      const page = await ctx.newPage();
      for (const route of routes) {
        const f: Finding = { route, viewport: `${w}x${h}`, theme, pageOverflowPx: 0, wide: [], smallTaps: 0, errors: [], status: null };
        const errs: string[] = [];
        const onErr = (e: Error) => errs.push(e.message.slice(0, 120));
        page.on("pageerror", onErr);
        try {
          const resp = await page.goto(base + route, { waitUntil: "domcontentloaded", timeout: 90000 });
          f.status = resp?.status() ?? null;
          await page.waitForLoadState("load", { timeout: 20000 }).catch(() => {});
          await page.addStyleTag({ content: "*{animation-duration:0s!important;animation-delay:0s!important;transition:none!important} .nx-preloader{display:none!important}" }).catch(() => {});
          await page.waitForTimeout(settle);
          const r = await inspect(page, w);
          f.pageOverflowPx = r.pageOverflowPx; f.wide = r.wide; f.smallTaps = r.smallTaps;
          if (!r.hasViewportMeta) f.errors.push("no viewport meta");
          if (shots) {
            const name = `${route.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "root"}__${w}x${h}__${theme}.png`;
            f.shot = join(out!, name);
            await page.screenshot({ path: f.shot, fullPage: true }).catch(() => { f.shot = undefined; });
          }
        } catch (e) { f.errors.push("nav: " + (e as Error).message.slice(0, 100)); }
        f.errors.push(...errs);
        page.off("pageerror", onErr);
        results.push(f);
        const bad = f.pageOverflowPx > 0 || f.wide.length > 0;
        console.log(`${bad ? "FAIL" : "ok  "} ${theme.padEnd(5)} ${f.viewport.padEnd(8)} ${String(f.status).padEnd(4)} ${route}` +
          (f.pageOverflowPx ? `  overflow=${f.pageOverflowPx}px` : "") + (f.wide.length ? `  wide=${f.wide.length}` : "") + (f.smallTaps ? `  smallTaps=${f.smallTaps}` : ""));
        if (bad) for (const x of f.wide.slice(0, 4)) console.log("       - " + x);
      }
      await ctx.close();
    }
  }
  await browser.close();
  const failing = results.filter((r) => r.pageOverflowPx > 0 || r.wide.length > 0);
  console.log(`\n${results.length} checks, ${failing.length} with overflow, ${results.filter((r) => r.status && r.status >= 400).length} HTTP>=400`);
  if (out) writeFileSync(join(out, "results.json"), JSON.stringify(results, null, 1));
  if (failing.length && !flag("no-fail")) process.exit(1);
}
main().catch((e) => { console.error(e); process.exit(2); });

