  "/dashboard/hosting", "/dashboard/email", "/dashboard/mail", "/dashboard/sites", "/dashboard/ssl",
  "/dashboard/support", "/dashboard/settings", "/dashboard/team", "/dashboard/feedback",
  "/dashboard/whats-new", "/dashboard/directory", "/dashboard/free-minecraft", "/dashboard/partner",
  "/dashboard/refer", "/dashboard/affiliate", "/dashboard/services", "/dashboard/volumes",
  "/dashboard/projects", "/dashboard/calendar", "/dashboard/claude-code", "/dashboard/build",
