     + overflow:auto rounding quirk, not real content overflow) — with
     only the Y axis clipped, that 1px of horizontal "overflow" was
     visible as a bright hairline down the right edge of the dark
     sidebar, right over its own light-mode page background. */
  return (
    <nav className="noscroll flex h-full flex-col gap-0.5 overflow-y-auto overflow-x-hidden px-3 pb-4" onClick={onNavigate}>
      {GROUPS.map((g) => {
        const items = NAV.filter((n) => n.group === g);
        if (!items.length) return null;
        return (
          <div key={g} className="flex flex-col gap-px">
            {!compact && (
              <span className="mt-3 mb-0.5 px-3 text-[9.5px] font-bold uppercase tracking-[0.11em] text-tx-faint">
                {g}
              </span>
            )}
            {compact && <span className="mx-auto my-1.5 h-px w-6 bg-rim-soft" />}
            {items.map((n) => (
              <NavLink key={n.href} {...n} compact={compact}
                       badge={badges[n.href] ? String(badges[n.href]) : n.badge}
                       active={n.href === activeHref} />
            ))}
          </div>
        );
      })}
    </nav>
  );
}

