     but the reader should never wait on a round-trip to see a badge clear. */
  const [notes, setNotes] = useState<Note[]>(notifications);
  const unread = notes.filter((n) => !n.readAt).length;

  /* Local only. The durable write is the panel's `markNotificationsRead`
