     `:root:has(.nx-shell-root)` — see the note there. The dashboard layout's
     inline script sets the class before first paint; this keeps it right on
     client-side entry to and exit from the dashboard. A layout effect, so it
     lands before the browser paints the shell. */
  useLayoutEffect(() => {
    const root = document.documentElement;
    root.classList.add("nx-portal");
    return () => root.classList.remove("nx-portal");
  }, []);
